using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.USR.Parentescos;namespace GraphApi.Services.USR.Parentescos{    public class ParentescosService : IParentescosService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public ParentescosService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadParentescos>> GetParentescos(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM usr.Parentescos (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadParentescos>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetParentescosDynamic(            int? parentescoID,            string? parentesco,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "ParentescoID, Parentesco, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM usr.Parentescos (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (parentescoID.HasValue)            {                vSql.Append(" AND ParentescoID = @ParentescoID");                vParameters.Add("ParentescoID",parentescoID);            }            if (!string.IsNullOrWhiteSpace(parentesco))            {                vSql.Append(" AND Parentesco LIKE @Parentesco");                vParameters.Add("Parentesco",$"%{parentesco}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadParentescos> CreateParentescos(clCreateParentescos objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO usr.Parentescos                (Parentesco, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@Parentesco, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.Parentesco,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT ParentescoID, Parentesco, bEliminado                FROM usr.Parentescos (NOLOCK)                WHERE ParentescoID = @ParentescoID;";            var vReadParams = new { ParentescoID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadParentescos>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Parentesco con ID {vNewId}.");            return vCreated;        }        public async Task<clReadParentescos?> UpdateParentescos(clUpdateParentescos objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("ParentescoID", objInput.ParentescoID);            if (objInput.Parentesco is not null)            {                vSets.Add("Parentesco = @Parentesco");                vParameters.Add("Parentesco", objInput.Parentesco);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE usr.Parentescos                SET {vSetClause}                WHERE ParentescoID = @ParentescoID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT ParentescoID, Parentesco, bEliminado                FROM usr.Parentescos (NOLOCK)                WHERE ParentescoID = @ParentescoID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadParentescos>(sSelect, new {  objInput.ParentescoID });        }        public async Task<bool> DeleteParentescos(int nParentescosID)        {            const string sSql = @"                DELETE FROM usr.Parentescos                WHERE ParentescoID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nParentescosID });            return vAffected > 0;        }    }}